 const addBlock=(kind:BlockKind,before?:string)=>{setSelectedElement('');const block=BLOCKS.find(b=>b.kind===kind)!;const section:Section={id:generateId(),kind,title:block.label,body:'请补充经确认的内容。',columns:3};const rows=[...draft.sections];const index=rows.findIndex(s=>s.id===before);rows.splice(index<0?rows.length:index,0,section);update({sections:rows,revision:draft.revision+1});setSelectedSection(section.id)}
 const dropBlock=(value:string,before?:string)=>{if(value.startsWith('new:'))addBlock(value.slice(4) as BlockKind,before);else if(value.startsWith('move:')){const id=value.slice(5);if(id===before)return;const section=draft.sections.find(s=>s.id===id);if(!section)return;const rows=draft.sections.filter(s=>s.id!==id);const index=rows.findIndex(s=>s.id===before);rows.splice(index<0?rows.length:index,0,section);update({sections:rows,revision:draft.revision+1})}}
