 const applyEdit=()=>{const text=editText.trim();if(!text)return;if(activeGap==='知识依据'||/^补充[:：]/.test(text)){const body=text.replace(/^补充[:：]/,'').trim();if(!body){notify('请输入需要补充的业务内容。');return}receiveSupplement({knowledgeReady:true,knowledgeName:'对话补充资料',sections:draft.sections.map(section=>section.kind==='text'||section.kind==='features'?{...section,body}:section)});setEditText('');return}handleEdit({title:draft.title});(()=>{let patch:Partial<Draft>={};let response='页面内容已更新。';if(selectedElement.includes(':image')||/换.*图片|替换.*图片/.test(text)){setMaterialTab('image');setModal('materials');response='请选择或上传用于替换的图片。'}else if(selectedElement.includes(':')&&!/^补充[:：]/.test(text)&&!activeGap){const [id,field]=selectedElement.split(':');const current=draft.elementTexts?.[selectedElement]||(!['title','body'].includes(field)?selectedTextFallback:id==='hero'?(field==='title'?draft.title:draft.subtitle):(draft.sections.find(x=>x.id===id)?.[field==='title'?'title':'body']||''));const replacement=/简洁|缩短|精简/.test(text)?current.split(/[，。；]/)[0]:/^(?:标题改为|改为|替换为|正文改为|标题[:：])/.test(text)?text.replace(/^(?:标题改为|改为|替换为|正文改为|标题[:：])[:：]?\s*/,''):'';if(replacement){if(!['title','body'].includes(field))patch.elementTexts={...draft.elementTexts,[selectedElement]:replacement};else if(id==='hero')patch=field==='title'?{title:replacement}:{subtitle:replacement};else patch.sections=draft.sections.map(x=>x.id===id?{...x,[field==='title'?'title':'body']:replacement}:x)}else response='请使用“改为：具体内容”提供替换文案，或使用“精简内容”。也可在右侧直接编辑文字。'}else if(activeGap==='视频素材'){if(/^https?:\/\//.test(text)){patch.videoUrl=text;response='视频区域已更新。';setActiveGap('')}else{setModal('video');response='请输入可访问的视频文件地址。'}}else if(activeGap==='页面主图'){setMaterialTab('image');setModal('materials');response='请上传图片，或选择示例素材。'}else if(activeGap==='关联产品'){const ids=mockProductsData.filter(p=>text.includes(p.name)).map(p=>p.id);if(ids.length){patch.productIds=ids;response='已将所选产品加入页面。';setActiveGap('')}else{setPendingProducts(draft.productIds);setModal('products');response='请从产品库选择对应产品。'}}else if(activeGap==='知识依据'||/^补充[:：]/.test(text)){patch={knowledgeReady:true,knowledgeName:'对话补充资料',sections:draft.sections.map(s=>s.id===selectedSection||(!draft.knowledgeReady&&(s.kind==='text'||s.kind==='features'))?{...s,body:text.replace(/^补充[:：]/,'')}:s)};response='检测助手 已完成补充资料的 Mock 校验，相关内容已更新。';setActiveGap('')}else if(selectedSection==='hero'){if(/简洁|缩短/.test(text))patch.title='精密制造，专业适配';else if(/布局|右图/.test(text))patch.layout=draft.layout==='split'?'center':'split';else if(/^(标题改为|改为|标题：|标题:)/.test(text))patch.title=text.replace(/^(标题改为|改为|标题：|标题:)[:：]?/,'');else response='请选择要修改的文字或图片，或使用“标题改为…”提供新文案。'}else if(/^(改为|正文改为)[:：]?/.test(text))patch.sections=draft.sections.map(s=>s.id===selectedSection?{...s,body:text.replace(/^(改为|正文改为)[:：]?/,'')}:s);else response='请选择具体文字后调整，或输入“正文改为：具体内容”。';update({...patch,revision:draft.revision+1,linkReady:false,messages:[...draft.messages,{role:'用户',text},{role:'生成助手',text:response}]});setAppliedEdit(response);setEditText('')})()}

 const publicLink=`${location.origin}${location.pathname}?studio-preview=1&page=${draft.id}`
